USER='You are signed in as a user (e.g. "Admin ShopView"), on the build under test. The Notifications Center feature is on.'
BELL='Open the Notifications inbox from the bell icon in the top navigation.'
def seed_note(n=1,extra=""):
    return (f'Seed {"a notification" if n==1 else str(n)+" notifications"} addressed to you: from another '
            f'signed-in user, open a work order (e.g. S2-17578) or part sale, click New Note, @-mention you '
            f'(or a tag group you belong to){extra}, and Save.')
